  FT["PH-H22676"] = {"id":"PH-H22676","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating Barangay Pulang-Lupa Dos in the Municipality of Las Pias, Metro Manila","orig":"Creating Barangay Pulang-Lupa Dos in the Municipality of Las Pias, Metro Manila"},"level":"law","status":"active","docNumber":"Presidential Decree No. 1330","issuingBody":"President of the Philippines","promulgatedDate":"1978-04-03","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 PD_01330_1978_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/06_总统令_PD/PD_01330_1978_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H22676-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following subdivisions known as Vergenville, Doña Julita, Doña Paz, St. Joseph, San\nAntonio, Martinville and Airmen's Village in Barangay Pulanglupa in the Municipality of Las Piñas, Metro\nManila, is hereby detached and separated therefrom to form and constitute into a distinct and independent\nbarangay which is created to be known as Barangay Pulanglupa Dos without affecting in any manner the legal\nexistence of the mother barangay."}},{"id":"PH-H22676-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Except as hereinafter provided, all provisions of law, now or hereafter applicable to regular\nbarangays, shall be applicable to Barangay Pulanglupa Dos."}},{"id":"PH-H22676-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The present elective barangay officials of Barangay Pulanglupa shall continue to perform their\nduties as such officials in the newly created Barangay Pulanglupa Dos until the barangay officials of said\nbarangay shall have been appointed by the President. Such officials so appointed shall hold office until their\nsuccessors shall have been elected in the regular elections for barangay officials following the issuance of this\nDecree and shall have qualified, unless sooner removed at the pleasure of the President. Such appointive\nofficers and employees as maybe necessary to organize or complete the government personnel of Barangay\nPulanglupa Dos shall be appointed as provided for under existing laws."}},{"id":"PH-H22676-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Upon the effectivity of this Decree, the proportionate share of the Barangay Pulanglupa Dos in\nthe obligations, funds assets and other property of Barangay Pulanglupa shall be transferred by the President\nto the newly created barangay upon the recommendation of the Commission on Audit."}},{"id":"PH-H22676-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"All laws or parts of laws as well as all executive orders or regulations, inconsistent herewith are\nhereby repealed or modified accordingly."}},{"id":"PH-H22676-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"This Decree shall take effect immediately.\nDone in the City of Manila, this 3rd day of April, in the year of Our Lord Nineteen Hundred and\nSeventy-Eight."}}],"pack":"ph-p160"};
  FT["PH-H22677"] = {"id":"PH-H22677","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Creating Barangay Manuyo Dos in the Municipality of Las Pias, Metro Manila","orig":"Creating Barangay Manuyo Dos in the Municipality of Las Pias, Metro Manila"},"level":"law","status":"active","docNumber":"Presidential Decree No. 1331","issuingBody":"President of the Philippines","promulgatedDate":"1978-04-03","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 PD_01331_1978_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/06_总统令_PD/PD_01331_1978_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H22677-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following subdivisions known as Canaynay, Olivarez-Guevarra and Gatchalian in Barangay\nManuyo, in the Municipality of Las Piñas, Metro Manila, is hereby detached and separated therefrom to form\nand constitute into a distinct and independent barangay which is created to be known as Barangay Manuyo\nDos without affecting in any manner the legal existence of the mother barangay."}},{"id":"PH-H22677-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Except as hereinafter provided, all provisions of law, now or hereafter applicable to regular\nbarangays, shall be applicable to Barangay Manuyo Dos."}},{"id":"PH-H22677-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The present elective barangay officials of Barangay Manuyo shall continue to perform their\nduties as such officials in the newly created Barangay Manuyo Dos until the barangay officials of said\nbarangay shall have been appointed by the President. Such officials so appointed shall hold office until their\nsuccessors shall have been elected in the regular elections for barangay officials following the issuance of this\nDecree and shall have qualified, unless sooner removed at the pleasure of the President. Such appointive\nofficers and employees as maybe necessary to organize or to complete the government personnel of Barangay\nManuyo Dos shall be appointed as provided for under existing laws."}},{"id":"PH-H22677-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Upon the effectivity of this Decree, the proportionate share of Barangay Manuyo Dos in the\nobligations, funds, assets and other property of Barangay Manuyo shall be transferred by the President to the\nnewly created barangay upon the recommendation of the Commission on Audit."}},{"id":"PH-H22677-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"All laws or parts of laws as well as all executive orders or regulations, inconsistent therewith are\nhereby repealed or modified accordingly."}},{"id":"PH-H22677-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"This Decree shall take effect immediately.\nDone in the City of Manila, this 3rd day of April, in the year of Our Lord, Nineteen Hundred and\nSeventy-Eight."}}],"pack":"ph-p160"};
